INSERT INTO "onboarding_questions" ("key", "packs", "kind", "question", "hint", "options", "sort_order") VALUES
	($q$about$q$, '{}'::text[], $q$short$q$, $q${"en":"What does your business do?","fr":"Que fait votre entreprise?"}$q$::jsonb, $q${"en":"In a sentence or two, e.g. “Family-run plumbing company, in business since 2009.”","fr":"En une ou deux phrases, p. ex. « Entreprise familiale de plomberie, en activité depuis 2009. »"}$q$::jsonb, $q$[]$q$::jsonb, 10),
	($q$services$q$, '{}'::text[], $q$long$q$, $q${"en":"What services or products do you offer, and at what price?","fr":"Quels services ou produits offrez-vous, et à quel prix?"}$q$::jsonb, $q${"en":"One per line, e.g. “Drain cleaning – from $149”. Write “call for a quote” where there is no set price.","fr":"Un par ligne, p. ex. « Débouchage – à partir de 149 $ ». Écrivez « sur devis » quand il n'y a pas de prix fixe."}$q$::jsonb, $q$[]$q$::jsonb, 20),
	($q$where$q$, '{}'::text[], $q$short$q$, $q${"en":"Where are you, or which towns and areas do you serve?","fr":"Où êtes-vous situé, ou quelles villes et quels secteurs desservez-vous?"}$q$::jsonb, $q${"en":"Your address, or the towns you travel to, e.g. “Guelph, Fergus and Elora”.","fr":"Votre adresse, ou les villes où vous vous déplacez, p. ex. « Gatineau, Chelsea et Cantley »."}$q$::jsonb, $q$[]$q$::jsonb, 30),
	($q$hours$q$, '{}'::text[], $q$short$q$, $q${"en":"When are you open?","fr":"Quelles sont vos heures d'ouverture?"}$q$::jsonb, $q${"en":"e.g. “Monday to Friday 8 am to 5 pm, Saturday 9 am to noon, closed Sunday”.","fr":"p. ex. « Du lundi au vendredi de 8 h à 17 h, le samedi de 9 h à midi, fermé le dimanche »."}$q$::jsonb, $q$[]$q$::jsonb, 40),
	($q$contact$q$, '{}'::text[], $q$short$q$, $q${"en":"How should customers reach you or book?","fr":"Comment les clients doivent-ils vous joindre ou réserver?"}$q$::jsonb, $q${"en":"Phone, email, a booking link, walk-ins…","fr":"Téléphone, courriel, lien de réservation, sans rendez-vous…"}$q$::jsonb, $q$[]$q$::jsonb, 50),
	($q$payment$q$, '{}'::text[], $q$short$q$, $q${"en":"Which payment methods do you accept?","fr":"Quels modes de paiement acceptez-vous?"}$q$::jsonb, $q${"en":"e.g. “Cash, debit, Visa, Mastercard, e-Transfer”.","fr":"p. ex. « Comptant, débit, Visa, Mastercard, virement Interac »."}$q$::jsonb, $q$[]$q$::jsonb, 60),
	($q$visit$q$, ARRAY[$q$auto-repair$q$, $q$restaurant$q$, $q$cafe-bakery$q$, $q$retail$q$, $q$personal-care$q$, $q$lodging$q$, $q$attractions$q$, $q$generic$q$]::text[], $q$short$q$, $q${"en":"Is there parking, and is your place accessible?","fr":"Y a-t-il du stationnement, et vos locaux sont-ils accessibles?"}$q$::jsonb, $q${"en":"e.g. “Free parking behind the building; step-free entrance”.","fr":"p. ex. « Stationnement gratuit derrière l'immeuble; entrée sans marche »."}$q$::jsonb, $q$[]$q$::jsonb, 70),
	($q$emergency$q$, ARRAY[$q$trades$q$]::text[], $q$short$q$, $q${"en":"Do you take emergency calls? When, and how should customers reach you for one?","fr":"Prenez-vous les appels d'urgence? Quand, et comment vous joindre dans ce cas?"}$q$::jsonb, $q${"en":"e.g. “24/7 for leaks and no heat: call 519-555-0100”, or “No emergency service”.","fr":"p. ex. « 24 h sur 24 pour les fuites et les pannes de chauffage : 819-555-0100 », ou « Pas de service d'urgence »."}$q$::jsonb, $q$[]$q$::jsonb, 80),
	($q$quotes$q$, ARRAY[$q$trades$q$]::text[], $q$short$q$, $q${"en":"How do quotes work? Is there a charge for an estimate or a service call?","fr":"Comment fonctionnent les devis? Facturez-vous l'estimation ou le déplacement?"}$q$::jsonb, $q${"en":"e.g. “Free estimates; $95 service call, waived if you go ahead with the work”.","fr":"p. ex. « Estimation gratuite; déplacement 95 $, offert si les travaux sont faits »."}$q$::jsonb, $q$[]$q$::jsonb, 90),
	($q$credentials$q$, ARRAY[$q$trades$q$]::text[], $q$short$q$, $q${"en":"Are you licensed and insured? Do you guarantee your work?","fr":"Êtes-vous titulaire d'une licence et assuré? Garantissez-vous vos travaux?"}$q$::jsonb, $q${"en":"Licence numbers, certifications, insurance and warranty, as you'd want customers to see them.","fr":"Numéros de licence, certifications, assurance et garantie, tels que vous voulez que les clients les voient."}$q$::jsonb, $q$[]$q$::jsonb, 100),
	($q$vehicles$q$, ARRAY[$q$auto-repair$q$]::text[], $q$short$q$, $q${"en":"Which vehicles do you work on? Any you don't?","fr":"Sur quels véhicules travaillez-vous? Y en a-t-il que vous ne prenez pas?"}$q$::jsonb, $q${"en":"e.g. “All makes, cars and light trucks; no diesel or motorcycles”.","fr":"p. ex. « Toutes marques, autos et camionnettes; pas de diesel ni de motos »."}$q$::jsonb, $q$[]$q$::jsonb, 110),
	($q$tires$q$, ARRAY[$q$auto-repair$q$]::text[], $q$short$q$, $q${"en":"Do you sell or store tires? How do seasonal changeovers work?","fr":"Vendez-vous ou entreposez-vous des pneus? Comment fonctionne le changement saisonnier?"}$q$::jsonb, $q${"en":"e.g. “Changeover on rims $49.99, by appointment; storage $80 a season”.","fr":"p. ex. « Changement sur jantes 49,99 $, sur rendez-vous; entreposage 80 $ par saison »."}$q$::jsonb, $q$[]$q$::jsonb, 120),
	($q$waiting$q$, ARRAY[$q$auto-repair$q$]::text[], $q$short$q$, $q${"en":"Can customers wait, get a ride or a loaner car while you work?","fr":"Les clients peuvent-ils attendre sur place, être raccompagnés ou avoir une voiture de courtoisie?"}$q$::jsonb, $q${"en":"e.g. “Waiting room with Wi-Fi; shuttle within 5 km”.","fr":"p. ex. « Salle d'attente avec Wi-Fi; navette dans un rayon de 5 km »."}$q$::jsonb, $q$[]$q$::jsonb, 130),
	($q$warranty$q$, ARRAY[$q$auto-repair$q$]::text[], $q$short$q$, $q${"en":"Do you offer a warranty on parts and labour?","fr":"Offrez-vous une garantie sur les pièces et la main-d'œuvre?"}$q$::jsonb, $q${"en":"e.g. “12 months or 20,000 km on parts and labour”.","fr":"p. ex. « 12 mois ou 20 000 km sur les pièces et la main-d'œuvre »."}$q$::jsonb, $q$[]$q$::jsonb, 140),
	($q$dietary$q$, ARRAY[$q$restaurant$q$, $q$cafe-bakery$q$]::text[], $q$short$q$, $q${"en":"Which dietary needs can you accommodate?","fr":"Quels besoins alimentaires pouvez-vous accommoder?"}$q$::jsonb, $q${"en":"e.g. “Vegetarian and vegan options; gluten-free bread on request; we can't guarantee nut-free”.","fr":"p. ex. « Options végétariennes et véganes; pain sans gluten sur demande; sans noix non garanti »."}$q$::jsonb, $q$[]$q$::jsonb, 150),
	($q$ordering$q$, ARRAY[$q$restaurant$q$, $q$cafe-bakery$q$]::text[], $q$short$q$, $q${"en":"Do you take reservations, takeout, delivery or catering orders? How?","fr":"Prenez-vous les réservations, les commandes à emporter, la livraison ou le traiteur? Comment?"}$q$::jsonb, $q${"en":"e.g. “Reservations by phone for 6 or more; takeout and delivery through our website”.","fr":"p. ex. « Réservations par téléphone à partir de 6 personnes; à emporter et livraison sur notre site »."}$q$::jsonb, $q$[]$q$::jsonb, 160),
	($q$custom_orders$q$, ARRAY[$q$cafe-bakery$q$]::text[], $q$short$q$, $q${"en":"Do you take custom orders, such as cakes for events? How far ahead?","fr":"Prenez-vous des commandes spéciales, comme des gâteaux pour un événement? Combien de temps à l'avance?"}$q$::jsonb, $q${"en":"e.g. “Custom cakes from $45, ordered at least 3 days ahead”.","fr":"p. ex. « Gâteaux personnalisés à partir de 45 $, commandés au moins 3 jours à l'avance »."}$q$::jsonb, $q$[]$q$::jsonb, 170),
	($q$groups$q$, ARRAY[$q$restaurant$q$, $q$attractions$q$]::text[], $q$short$q$, $q${"en":"Do you host groups, private events or school visits?","fr":"Accueillez-vous des groupes, des événements privés ou des sorties scolaires?"}$q$::jsonb, $q${"en":"e.g. “Private room for up to 30; group rates from 15 people, booked a week ahead”.","fr":"p. ex. « Salle privée jusqu'à 30 personnes; tarif de groupe dès 15 personnes, réservé une semaine à l'avance »."}$q$::jsonb, $q$[]$q$::jsonb, 180),
	($q$brands$q$, ARRAY[$q$retail$q$]::text[], $q$short$q$, $q${"en":"Which brands or kinds of products do you carry?","fr":"Quelles marques ou quels types de produits offrez-vous?"}$q$::jsonb, $q${"en":"e.g. “Outdoor clothing and footwear: Arc'teryx, Merrell, local wool socks”.","fr":"p. ex. « Vêtements et chaussures de plein air : Arc'teryx, Merrell, bas de laine d'ici »."}$q$::jsonb, $q$[]$q$::jsonb, 190),
	($q$pickup$q$, ARRAY[$q$retail$q$]::text[], $q$choice$q$, $q${"en":"Can customers order online, reserve an item, or get it delivered?","fr":"Les clients peuvent-ils commander en ligne, réserver un article ou se faire livrer?"}$q$::jsonb, $q${"en":"","fr":""}$q$::jsonb, $q$[{"en":"In store only","fr":"En magasin seulement"},{"en":"Online shop with in-store pickup","fr":"Boutique en ligne avec cueillette en magasin"},{"en":"Online shop with delivery","fr":"Boutique en ligne avec livraison"},{"en":"We hold items by phone","fr":"Nous mettons des articles de côté par téléphone"}]$q$::jsonb, 200),
	($q$returns$q$, ARRAY[$q$retail$q$]::text[], $q$short$q$, $q${"en":"What is your return and exchange policy?","fr":"Quelle est votre politique de retour et d'échange?"}$q$::jsonb, $q${"en":"e.g. “Exchange or store credit within 30 days with receipt; final sale items excluded”.","fr":"p. ex. « Échange ou crédit en magasin dans les 30 jours avec reçu; articles en solde finale exclus »."}$q$::jsonb, $q$[]$q$::jsonb, 210),
	($q$appointments$q$, ARRAY[$q$personal-care$q$]::text[], $q$choice$q$, $q${"en":"Do you take walk-ins, or by appointment only?","fr":"Acceptez-vous les clients sans rendez-vous, ou seulement sur rendez-vous?"}$q$::jsonb, $q${"en":"","fr":""}$q$::jsonb, $q$[{"en":"By appointment only","fr":"Sur rendez-vous seulement"},{"en":"Walk-ins welcome","fr":"Sans rendez-vous bienvenus"},{"en":"Both, appointments first","fr":"Les deux, priorité aux rendez-vous"}]$q$::jsonb, 220),
	($q$first_visit$q$, ARRAY[$q$personal-care$q$]::text[], $q$short$q$, $q${"en":"Is there anything new clients should know before their first visit?","fr":"Les nouveaux clients doivent-ils savoir quelque chose avant leur première visite?"}$q$::jsonb, $q${"en":"e.g. “Arrive 10 minutes early; a patch test is needed 48 hours before any colour”.","fr":"p. ex. « Arrivez 10 minutes à l'avance; un test cutané est requis 48 heures avant une coloration »."}$q$::jsonb, $q$[]$q$::jsonb, 230),
	($q$cancellation$q$, ARRAY[$q$personal-care$q$, $q$lodging$q$]::text[], $q$short$q$, $q${"en":"What is your cancellation policy?","fr":"Quelle est votre politique d'annulation?"}$q$::jsonb, $q${"en":"e.g. “Free cancellation up to 24 hours before; 50% charged after that”.","fr":"p. ex. « Annulation gratuite jusqu'à 24 heures avant; 50 % facturé ensuite »."}$q$::jsonb, $q$[]$q$::jsonb, 240),
	($q$checkin$q$, ARRAY[$q$lodging$q$]::text[], $q$short$q$, $q${"en":"What are your check-in and check-out times?","fr":"Quelles sont vos heures d'arrivée et de départ?"}$q$::jsonb, $q${"en":"e.g. “Check-in from 4 pm, check-out by 11 am; late arrivals use the key box”.","fr":"p. ex. « Arrivée dès 16 h, départ avant 11 h; boîte à clés pour les arrivées tardives »."}$q$::jsonb, $q$[]$q$::jsonb, 250),
	($q$amenities$q$, ARRAY[$q$lodging$q$]::text[], $q$short$q$, $q${"en":"What is included in a stay?","fr":"Qu'est-ce qui est inclus dans un séjour?"}$q$::jsonb, $q${"en":"e.g. “Breakfast, Wi-Fi, parking and the pool; kayaks for $20 a day”.","fr":"p. ex. « Déjeuner, Wi-Fi, stationnement et piscine; kayaks à 20 $ par jour »."}$q$::jsonb, $q$[]$q$::jsonb, 260),
	($q$pets$q$, ARRAY[$q$lodging$q$]::text[], $q$choice$q$, $q${"en":"Are pets welcome?","fr":"Les animaux sont-ils acceptés?"}$q$::jsonb, $q${"en":"","fr":""}$q$::jsonb, $q$[{"en":"Pets welcome","fr":"Animaux bienvenus"},{"en":"In some rooms only","fr":"Dans certaines chambres seulement"},{"en":"No pets","fr":"Pas d'animaux"}]$q$::jsonb, 270),
	($q$tickets$q$, ARRAY[$q$attractions$q$]::text[], $q$short$q$, $q${"en":"How do tickets or admission work? Do visitors need to book ahead?","fr":"Comment fonctionnent les billets ou l'admission? Faut-il réserver à l'avance?"}$q$::jsonb, $q${"en":"e.g. “Adults $18, children under 5 free; online booking recommended on weekends”.","fr":"p. ex. « Adultes 18 $, gratuit pour les moins de 5 ans; réservation en ligne conseillée la fin de semaine »."}$q$::jsonb, $q$[]$q$::jsonb, 280),
	($q$season$q$, ARRAY[$q$attractions$q$]::text[], $q$choice$q$, $q${"en":"Are you open all year, or for a season?","fr":"Êtes-vous ouvert toute l'année, ou en saison?"}$q$::jsonb, $q${"en":"","fr":""}$q$::jsonb, $q$[{"en":"Open all year","fr":"Ouvert toute l'année"},{"en":"Summer season only","fr":"En été seulement"},{"en":"Winter season only","fr":"En hiver seulement"}]$q$::jsonb, 290),
	($q$faq$q$, '{}'::text[], $q$long$q$, $q${"en":"What do customers ask you most often, and what do you tell them?","fr":"Quelles questions vos clients posent-ils le plus souvent, et que leur répondez-vous?"}$q$::jsonb, $q${"en":"One per line, e.g. “Do you work weekends? – Saturdays only, by appointment”.","fr":"Une par ligne, p. ex. « Travaillez-vous la fin de semaine? – Le samedi seulement, sur rendez-vous »."}$q$::jsonb, $q$[]$q$::jsonb, 900);
